# Utilidades de traducción (español / inglés).
# Los textos están en R/i18n_es.R y R/i18n_en.R. Los elementos estáticos de la
# interfaz se marcan con i18n() y se traducen en el navegador (www/i18n.js) sin
# recargar la página; las salidas dinámicas usan tr(clave, idioma).

LANGS <- c("es", "en")

i18n_dict <- function() list(es = TR_ES, en = TR_EN)

tr <- function(key, lang = "es", ...) {
  txt <- i18n_dict()[[lang]][[key]]
  if (is.null(txt)) txt <- TR_ES[[key]]
  if (is.null(txt)) stop("Clave de traducción desconocida: ", key)
  if (...length()) sprintf(txt, ...) else txt
}

# Elemento de texto traducible en el navegador (por defecto, en español).
i18n <- function(key, tag = shiny::span) {
  tag(`data-i18n` = key, shiny::HTML(TR_ES[[key]]))
}

// Cambio de idioma en el cliente: sustituye el contenido de los elementos con
// data-i18n usando el diccionario que envía el servidor.
(function () {
  var dict = null;

  Shiny.addCustomMessageHandler("set-lang", function (msg) {
    if (msg.dict) dict = msg.dict;
    var d = dict && dict[msg.lang];
    if (!d) return;
    document.documentElement.lang = msg.lang;
    document.querySelectorAll("[data-i18n]").forEach(function (el) {
      var txt = d[el.getAttribute("data-i18n")];
      if (txt !== undefined) el.innerHTML = txt;
    });
    // Texto de ayuda del selector de ficheros (solo si aún no hay fichero)
    var fileText = $("#file").closest(".input-group").find("input[type=text]");
    fileText.attr("placeholder", d.no_file);
    if (window.MathJax && MathJax.Hub) MathJax.Hub.Queue(["Typeset", MathJax.Hub]);
  });

  $(document).on("shiny:connected", function () {
    var lang = (navigator.language || "es").slice(0, 2).toLowerCase();
    Shiny.setInputValue("browser_lang", lang);
  });
})();
